--
-- Table structure for table `edges`
--

DROP TABLE IF EXISTS `edges`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `edges` (
  `edge_id` bigint NOT NULL AUTO_INCREMENT COMMENT '엣지 번호',
  `from_point_id` bigint NOT NULL COMMENT '시작포인트 번호',
  `to_point_id` bigint NOT NULL COMMENT '도착포인트 번호',
  `edge_code` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `weight` decimal(10,2) NOT NULL,
  `photo_s3` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'S3 이미지 경로',
  `use_stair` tinyint(1) NOT NULL DEFAULT '0',
  PRIMARY KEY (`edge_id`),
  KEY `idx_edges_from` (`from_point_id`),
  KEY `idx_edges_to` (`to_point_id`),
  CONSTRAINT `fk_edges_from_point` FOREIGN KEY (`from_point_id`) REFERENCES `points` (`point_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_edges_to_point` FOREIGN KEY (`to_point_id`) REFERENCES `points` (`point_id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=211 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='엣지';
/*!40101 SET character_set_client = @saved_cs_client */;

